--- app/models/push_subscription.rb
class PushSubscription < ApplicationRecord
  belongs_to :account, default: -> { user.account }
  belongs_to :user

  before_validation :set_endpoint_digest

  validates :endpoint, presence: true, length: { maximum: 2048 }
  validates :endpoint_digest, presence: true, uniqueness: { scope: :user_id }
  validates :p256dh_key, :auth_key, presence: true, length: { maximum: 255 }
  validate :endpoint_uses_https

  private
    def set_endpoint_digest
      self.endpoint_digest = Digest::SHA256.hexdigest(endpoint) if endpoint.present?
    end

    def endpoint_uses_https
      uri = URI.parse(endpoint) if endpoint.present?
      unless uri.is_a?(URI::HTTPS) && uri.host.present? && uri.userinfo.nil?
        errors.add(:endpoint, "must be a valid HTTPS URL")
      end
    rescue URI::InvalidURIError
      errors.add(:endpoint, "must be a valid HTTPS URL")
    end
end
